SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(i),'identity',to_jsonb(pg_identify_object('pg_class'::regclass,i.indexrelid,0)),'table',to_jsonb(pg_identify_object('pg_class'::regclass,i.indrelid,0)),'definition',pg_get_indexdef(i.indexrelid,0,false),'columns',(SELECT jsonb_agg(jsonb_build_object('position',x.position,'attnum',x.attnum,'identity',CASE WHEN x.attnum<>0 THEN to_jsonb(pg_identify_object('pg_class'::regclass,i.indrelid,x.attnum)) END) ORDER BY x.position) FROM unnest(i.indkey::smallint[]) WITH ORDINALITY x(attnum,position))) ORDER BY i.indexrelid),'[]'::jsonb) AS payload FROM pg_index i WHERE i.indexrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture